120	// CountCheckpointsInTree counts checkpoint shard directories in a /full/* tree.
121	// The tree structure is <id[:2]>/<id[2:]>/ — we count second-level directories
122	// across all shard prefixes. Returns 0 for an empty tree.
123	func (s *V2GitStore) CountCheckpointsInTree(treeHash plumbing.Hash) (int, error) {
124		if treeHash == plumbing.ZeroHash {
125			return 0, nil
126		}
127	
128		tree, err := s.repo.TreeObject(treeHash)
129		if err != nil {
130			return 0, fmt.Errorf("failed to read tree: %w", err)
131		}
132	
133		count := 0
134		if err := WalkCheckpointShards(s.repo, tree, func(_ id.CheckpointID, _ plumbing.Hash) error {
135			count++
136			return nil
137		}); err != nil {
138			return 0, err
139		}
140	
141		return count, nil
142	}
