144	// AddGenerationJSONToTree adds generation.json to an existing root tree, returning
145	// a new root tree hash. Preserves all existing entries (shard directories, etc.).
146	func (s *V2GitStore) AddGenerationJSONToTree(rootTreeHash plumbing.Hash, gen GenerationMetadata) (plumbing.Hash, error) {
147		entry, err := s.marshalGenerationBlob(gen)
148		if err != nil {
149			return plumbing.ZeroHash, err
150		}
151	
152		return UpdateSubtree(s.repo, rootTreeHash, nil, []object.TreeEntry{entry},
153			UpdateSubtreeOptions{MergeMode: MergeKeepExisting})
154	}
