260	func (s *V2GitStore) v2MainTree() (*object.Tree, error) {
261		ref, err := s.repo.Reference(plumbing.ReferenceName(paths.V2MainRefName), true)
262		if err != nil {
263			return nil, fmt.Errorf("failed to read v2 main ref: %w", err)
264		}
265		commit, err := s.repo.CommitObject(ref.Hash())
266		if err != nil {
267			return nil, fmt.Errorf("failed to read v2 main commit: %w", err)
268		}
269		tree, err := commit.Tree()
270		if err != nil {
271			return nil, fmt.Errorf("failed to read v2 main tree: %w", err)
272		}
273		return tree, nil
274	}
