337	// AggregateTranscriptTimestamps derives a generation timestamp envelope from
338	// transcripts already in memory, using the same first/last-event semantics
339	// as ComputeGenerationTimestampsFromTrees but skipping the blob reads.
340	func AggregateTranscriptTimestamps(transcripts [][]byte) (GenerationMetadata, bool) {
341		var gen GenerationMetadata
342		found := false
343		for _, transcript := range transcripts {
344			if len(transcript) == 0 {
345				continue
346			}
347			if r, ok := timestampRangeFromTranscript(transcript); ok {
348				mergeGenerationRange(&gen, &found, r)
349			}
350		}
351		return gen, found
352	}
353	
354	func timestampRangeFromTranscript(transcript []byte) (GenerationMetadata, bool) {
355		reader := bufio.NewReader(bytes.NewReader(transcript))
356		var gen GenerationMetadata
357		found := false
358	
359		for {
360			line, err := reader.ReadBytes('\n')
361			if trimmed := bytes.TrimSpace(line); len(trimmed) > 0 {
362				var event struct {
363					Timestamp string `json:"timestamp"`
364				}
365				if jsonErr := json.Unmarshal(trimmed, &event); jsonErr == nil && event.Timestamp != "" {
366					if ts, parseErr := time.Parse(time.RFC3339Nano, event.Timestamp); parseErr == nil {
367						MergeGenerationTime(&gen, &found, ts.UTC())
368					}
369				}
370			}
371			if errors.Is(err, io.EOF) {
372				break
373			}
374			if err != nil {
375				break
376			}
377		}
378	
379		return gen, found
380	}
