382	func mergeGenerationRange(dst *GenerationMetadata, found *bool, src GenerationMetadata) {
383		MergeGenerationTime(dst, found, src.OldestCheckpointAt)
384		MergeGenerationTime(dst, found, src.NewestCheckpointAt)
385	}
