448	// NextGenerationNumber returns the next sequential generation number for archiving.
449	// Scans existing archived refs and returns max+1. Returns 1 if no archives exist.
450	func (s *V2GitStore) NextGenerationNumber() (int, error) {
451		archived, err := s.ListArchivedGenerations()
452		if err != nil {
453			return 0, err
454		}
455	
456		var maxNum int64
457		for _, name := range archived {
458			n, parseErr := strconv.ParseInt(name, 10, 64)
459			if parseErr != nil {
460				continue // skip unparseable entries
461			}
462			if n > maxNum {
463				maxNum = n
464			}
465		}
466		return int(maxNum) + 1, nil
467	}
