469	// RotateCurrentGenerationIfNeeded archives /full/current when it has reached
470	// maxCheckpoints. It returns the archived ref name when this call completes
471	// a rotation.
472	func (s *V2GitStore) RotateCurrentGenerationIfNeeded(ctx context.Context, maxCheckpoints int) (plumbing.ReferenceName, bool, error) {
473		if maxCheckpoints <= 0 {
474			maxCheckpoints = s.maxCheckpoints()
475		}
476	
477		// This is a 2-phase operation:
478		//
479		//  1. Archive: determine the next generation number, create a new ref pointing
480		//     to the current /full/current commit.
481		//  2. Reset: create a fresh orphan commit with an empty tree, point
482		//     /full/current at it.
483		refName := plumbing.ReferenceName(paths.V2FullCurrentRefName)
484	
485		// Guard against concurrent rotation: re-read /full/current and check if
486		// it's still above the threshold. If not, another instance already rotated.
487		_, currentTreeHash, err := s.GetRefState(refName)
488		if err != nil {
489			return "", false, fmt.Errorf("rotation: failed to read /full/current: %w", err)
490		}
491		checkpointCount, err := s.CountCheckpointsInTree(currentTreeHash)
492		if err != nil {
493			return "", false, fmt.Errorf("rotation: failed to count checkpoints: %w", err)
494		}
495		if checkpointCount < maxCheckpoints {
496			return "", false, nil
497		}
498	
499		currentRef, err := s.repo.Reference(refName, true)
500		if err != nil {
501			return "", false, fmt.Errorf("rotation: failed to read /full/current ref: %w", err)
502		}
503	
504		archiveNumber, err := s.NextGenerationNumber()
505		if err != nil {
506			return "", false, fmt.Errorf("rotation: failed to determine next generation number: %w", err)
507		}
508	
509		// Phase 1: Prepare archive and reset commits without changing refs yet.
510		// If the archive ref already exists, another instance already rotated — skip.
511		archiveRefName := ArchivedGenerationRefName(archiveNumber)
512		if _, refErr := s.repo.Reference(archiveRefName, true); refErr == nil {
513			logging.Info(ctx, "rotation: archive ref already exists, skipping",
514				slog.String("archive_ref", string(archiveRefName)),
515			)
516			return archiveRefName, false, nil
517		}
518	
519		// Write generation.json to the current tree before archiving.
520		gen := s.computeGenerationTimestamps(currentTreeHash)
521		archiveTreeHash, err := s.AddGenerationJSONToTree(currentTreeHash, gen)
522		if err != nil {
523			return "", false, fmt.Errorf("rotation: failed to add generation.json: %w", err)
524		}
525	
526		authorName, authorEmail := GetGitAuthorFromRepo(s.repo)
527		archiveCommitHash, err := CreateCommit(ctx, s.repo, archiveTreeHash, currentRef.Hash(), "Archive generation", authorName, authorEmail)
528		if err != nil {
529			return "", false, fmt.Errorf("rotation: failed to create archive commit: %w", err)
530		}
531	
532		// Create fresh orphan /full/current (empty tree, no generation.json).
533		emptyTreeHash, err := BuildTreeFromEntries(ctx, s.repo, make(map[string]object.TreeEntry))
534		if err != nil {
535			return "", false, fmt.Errorf("rotation: failed to build empty tree: %w", err)
536		}
537	
538		orphanCommitHash, err := CreateCommit(ctx, s.repo, emptyTreeHash, plumbing.ZeroHash, "Start generation", authorName, authorEmail)
539		if err != nil {
540			return "", false, fmt.Errorf("rotation: failed to create orphan commit: %w", err)
541		}
542	
543		// Verify /full/current hasn't been advanced by another writer since we read it.
544		// If it changed, abort before recording a publication marker.
545		postArchiveRef, err := s.repo.Reference(refName, true)
546		if err != nil {
547			return "", false, fmt.Errorf("rotation: failed to re-read /full/current: %w", err)
548		}
549		if postArchiveRef.Hash() != currentRef.Hash() {
550			logging.Info(ctx, "rotation: /full/current changed during rotation, aborting reset")
551			return archiveRefName, false, nil
552		}
553	
554		publication := PendingV2FullGenerationPublication{
555			ArchiveRefName:           archiveRefName.String(),
556			ArchiveCommitHash:        archiveCommitHash.String(),
557			PreviousFullCurrentHash:  currentRef.Hash().String(),
558			ResetFullCurrentRootHash: orphanCommitHash.String(),
559			QueuedAt:                 time.Now().UTC(),
560		}
561	
562		// The commit objects above are not reachable from the v2 refs yet. Record
563		// the pending publication before moving refs. Pre-push drops stale reset
564		// handoffs until the newest queued reset root is in local /full/current
565		// history, then publishes the queued archive refs together.
566		if err := s.AppendPendingFullGenerationPublication(ctx, publication); err != nil {
567			return "", false, fmt.Errorf("rotation: failed to record pending full rotation: %w", err)
568		}
569		keepPendingPublication := false
570		defer func() {
571			if keepPendingPublication {
572				return
573			}
574			if removeErr := s.RemovePendingFullGenerationPublications(ctx, []PendingV2FullGenerationPublication{publication}); removeErr != nil {
575				logging.Warn(ctx, "rotation: failed to remove pending full rotation after failed rotation",
576					slog.String("error", removeErr.Error()),
577					slog.String("archive_ref", string(archiveRefName)),
578					slog.String("previous_full_current_hash", currentRef.Hash().String()),
579					slog.String("archive_commit_hash", archiveCommitHash.String()),
580					slog.String("reset_full_current_root_hash", orphanCommitHash.String()),
581				)
582			}
583		}()
584	
585		// Phase 2: publish local refs after the pending publication marker exists.
586		if _, refErr := s.repo.Reference(archiveRefName, true); refErr == nil {
587			logging.Info(ctx, "rotation: archive ref already exists, skipping",
588				slog.String("archive_ref", string(archiveRefName)),
589			)
590			return archiveRefName, false, nil
591		}
592		archiveRef := plumbing.NewHashReference(archiveRefName, archiveCommitHash)
593		if err := s.repo.Storer.SetReference(archiveRef); err != nil {
594			return "", false, fmt.Errorf("rotation: failed to update archived ref %s: %w", archiveRefName, err)
595		}
596	
597		reset, err := s.resetFullCurrentRefIfUnchanged(ctx, refName, postArchiveRef, orphanCommitHash)
598		if err != nil {
599			return "", false, err
600		}
601		if !reset {
602			return archiveRefName, false, nil
603		}
604	
605		keepPendingPublication = true
606		logging.Info(ctx, "generation rotation complete",
607			slog.Int("archived_generation", archiveNumber),
608			slog.String("archive_ref", string(archiveRefName)),
609		)
610	
611		return archiveRefName, true, nil
612	}
