615		newRef := plumbing.NewHashReference(refName, newHash)
616		if err := s.repo.Storer.CheckAndSetReference(newRef, expectedRef); err != nil {
617			if errors.Is(err, storage.ErrReferenceHasChanged) {
618				logging.Info(ctx, "rotation: /full/current changed before reset, leaving current ref intact")
619				return false, nil
620			}
621			return false, fmt.Errorf("rotation: failed to reset /full/current: %w", err)
622		}
623		return true, nil
624	}
