69	func (s *V2GitStore) RemovePendingFullGenerationPublications(ctx context.Context, publications []PendingV2FullGenerationPublication) error {
70		if len(publications) == 0 {
71			return nil
72		}
73		return s.withPendingFullGenerationPublicationLock(ctx, func() error {
74			state, err := s.readPendingFullGenerationPublicationState(ctx)
75			if err != nil {
76				return err
77			}
78			previousCount := len(state.Publications)
79			state.Publications = removePendingFullGenerationPublications(state.Publications, publications)
80			if len(state.Publications) == previousCount {
81				return nil
82			}
83			if len(state.Publications) == 0 {
84				return s.removePendingFullGenerationPublicationFile(ctx)
85			}
86			state.Version = pendingV2FullGenerationPublicationVersion
87			return s.writePendingFullGenerationPublicationState(ctx, state)
88		})
89	}
