115		path, err := s.pendingFullGenerationPublicationFilePath(ctx)
116		if err != nil {
117			return err
118		}
119		if err := os.Remove(path); err != nil && !os.IsNotExist(err) {
120			return fmt.Errorf("remove pending v2 full generation publications: %w", err)
121		}
122		return nil
123	}
