125	func (s *V2GitStore) withPendingFullGenerationPublicationLock(ctx context.Context, fn func() error) (err error) {
126		lockPath, err := s.pendingFullGenerationPublicationLockPath(ctx)
127		if err != nil {
128			return err
129		}
130		if err := os.MkdirAll(filepath.Dir(lockPath), 0o750); err != nil {
131			return fmt.Errorf("create pending v2 full generation publication lock dir: %w", err)
132		}
133		if err := lockfile.WithTimeout(ctx, lockPath, pendingV2FullGenerationPublicationLockTTL, fn); err != nil {
134			return fmt.Errorf("pending v2 full generation publication lock: %w", err)
135		}
136		return nil
137	}
