139	func (s *V2GitStore) readPendingFullGenerationPublicationState(ctx context.Context) (pendingV2FullGenerationPublicationState, error) {
140		path, err := s.pendingFullGenerationPublicationFilePath(ctx)
141		if err != nil {
142			return pendingV2FullGenerationPublicationState{}, err
143		}
144		data, err := os.ReadFile(path) //nolint:gosec // path is under git common dir
145		if os.IsNotExist(err) {
146			return pendingV2FullGenerationPublicationState{Version: pendingV2FullGenerationPublicationVersion}, nil
147		}
148		if err != nil {
149			return pendingV2FullGenerationPublicationState{}, fmt.Errorf("read pending v2 full generation publications: %w", err)
150		}
151	
152		var state pendingV2FullGenerationPublicationState
153		if err := json.Unmarshal(data, &state); err != nil {
154			return pendingV2FullGenerationPublicationState{}, fmt.Errorf("parse pending v2 full generation publications: %w", err)
155		}
156		if state.Version != pendingV2FullGenerationPublicationVersion {
157			return pendingV2FullGenerationPublicationState{}, fmt.Errorf("unsupported pending v2 full generation publication version %d", state.Version)
158		}
159		return state, nil
160	}
161	
162	func (s *V2GitStore) writePendingFullGenerationPublicationState(ctx context.Context, state pendingV2FullGenerationPublicationState) error {
163		path, err := s.pendingFullGenerationPublicationFilePath(ctx)
164		if err != nil {
165			return err
166		}
167		if err := os.MkdirAll(filepath.Dir(path), 0o750); err != nil {
168			return fmt.Errorf("create pending v2 full generation publication dir: %w", err)
169		}
170	
171		data, err := jsonutil.MarshalIndentWithNewline(state, "", "  ")
172		if err != nil {
173			return fmt.Errorf("marshal pending v2 full generation publications: %w", err)
174		}
175	
176		tmpFile, err := os.CreateTemp(filepath.Dir(path), pendingV2FullGenerationPublicationFile+".*.tmp")
177		if err != nil {
178			return fmt.Errorf("create pending v2 full generation publication temp file: %w", err)
179		}
180		tmpName := tmpFile.Name()
181		removeTmp := true
182		defer func() {
183			if removeTmp {
184				_ = os.Remove(tmpName)
185			}
186		}()
187	
188		if _, err := tmpFile.Write(data); err != nil {
189			_ = tmpFile.Close()
190			return fmt.Errorf("write pending v2 full generation publications: %w", err)
191		}
192		if err := tmpFile.Close(); err != nil {
193			return fmt.Errorf("close pending v2 full generation publications: %w", err)
194		}
195		if err := os.Rename(tmpName, path); err != nil {
196			return fmt.Errorf("replace pending v2 full generation publications: %w", err)
197		}
198		removeTmp = false
199		return nil
200	}
