218	func (s *V2GitStore) gitCommonDir(ctx context.Context) (string, error) {
219		s.commonDirOnce.Do(func() {
220			s.commonDir, s.commonDirErr = resolveGitCommonDir(ctx, s.repo)
221		})
222		return s.commonDir, s.commonDirErr
223	}
224	
225	func resolveGitCommonDir(ctx context.Context, repo *git.Repository) (string, error) {
226		worktree, err := repo.Worktree()
227		if err != nil {
228			return "", fmt.Errorf("open worktree for pending v2 full generation publications: %w", err)
229		}
230		root := worktree.Filesystem().Root()
231		if root == "" {
232			return "", errors.New("resolve worktree root for pending v2 full generation publications")
233		}
234	
235		cmd := exec.CommandContext(ctx, "git", "-C", root, "rev-parse", "--git-common-dir")
236		output, err := cmd.Output()
237		if err != nil {
238			return "", fmt.Errorf("resolve git common dir for pending v2 full generation publications: %w", err)
239		}
240		commonDir := strings.TrimSpace(string(output))
241		if commonDir == "" {
242			return "", errors.New("resolve git common dir for pending v2 full generation publications: empty output")
243		}
244		if !filepath.IsAbs(commonDir) {
245			commonDir = filepath.Join(root, commonDir)
246		}
247		return filepath.Clean(commonDir), nil
248	}
