209	func pendingFullArchiveRefs(publications []checkpoint.PendingV2FullGenerationPublication) []plumbing.ReferenceName {
210		seen := make(map[plumbing.ReferenceName]struct{}, len(publications))
211		refs := make([]plumbing.ReferenceName, 0, len(publications))
212		for _, publication := range publications {
213			suffix, ok := strings.CutPrefix(publication.ArchiveRefName, paths.V2FullRefPrefix)
214			if !ok || !checkpoint.GenerationRefPattern.MatchString(suffix) {
215				continue
216			}
217			refName := plumbing.ReferenceName(paths.V2FullRefPrefix + suffix)
218			if _, ok := seen[refName]; ok {
219				continue
220			}
221			seen[refName] = struct{}{}
222			refs = append(refs, refName)
223		}
224		return refs
225	}
