227	func pendingFullCurrentResetPublications(publications []checkpoint.PendingV2FullGenerationPublication) []checkpoint.PendingV2FullGenerationPublication {
228		resetPublications := make([]checkpoint.PendingV2FullGenerationPublication, 0, len(publications))
229		for _, publication := range publications {
230			if publication.PreviousFullCurrentHash == "" && publication.ResetFullCurrentRootHash == "" {
231				continue
232			}
233			resetPublications = append(resetPublications, publication)
234		}
235		return resetPublications
236	}
